import type { ImportMapConfig } from './types'

export type ImportMapConfigValidation
  = | { valid: true, value: ImportMapConfig | null | undefined }
    | { valid: false, diagnostic: string }

const VALIDATION_BASE = 'https://wippy.invalid/import-map/'
function hasControlCharacters(value: string): boolean {
  return Array.from(value).some(character => character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127)
}
const URL_SCHEME = /^([a-z][a-z\d+.-]*):/i

function isRecord(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Array.isArray(value))
    return false
  const prototype = Object.getPrototypeOf(value)
  if (prototype === null)
    return true
  const constructor = Object.getOwnPropertyDescriptor(prototype, 'constructor')?.value
  return Object.getPrototypeOf(prototype) === null
    && typeof constructor === 'function'
    && Function.prototype.toString.call(constructor) === Function.prototype.toString.call(Object)
}

function hasValidHttpUrl(value: string): boolean {
  if (!value || value.trim() !== value || value.includes('\\') || hasControlCharacters(value))
    return false

  const scheme = value.match(URL_SCHEME)?.[1]?.toLowerCase()
  if (scheme && scheme !== 'http' && scheme !== 'https')
    return false

  try {
    const url = new URL(value, VALIDATION_BASE)
    return url.protocol === 'http:' || url.protocol === 'https:'
  }
  catch {
    return false
  }
}

function isScopeUrlReference(value: string): boolean {
  return hasValidHttpUrl(value)
}

function isUrlLikeSpecifier(value: string): boolean {
  return value.startsWith('/') || value.startsWith('./') || value.startsWith('../') || URL_SCHEME.test(value)
}

function resolveAgainstBase(value: string, baseURL?: string | URL): string {
  if (!baseURL)
    return value

  try {
    return new URL(value, baseURL).href
  }
  catch {
    return value
  }
}

function isMappingAddress(value: string): boolean {
  if (!hasValidHttpUrl(value))
    return false

  const scheme = value.match(URL_SCHEME)?.[1]?.toLowerCase()
  if (!scheme && !value.startsWith('/') && !value.startsWith('./') && !value.startsWith('../'))
    return false

  return true
}

function normalizeMappings(input: unknown): Record<string, string> | null {
  if (!isRecord(input))
    return null

  const output: Record<string, string> = Object.create(null)
  for (const [specifier, target] of Object.entries(input)) {
    if (!specifier || specifier.trim() !== specifier || hasControlCharacters(specifier) || specifier.includes('\\'))
      return null
    if (typeof target !== 'string' || !isMappingAddress(target))
      return null
    if (specifier.endsWith('/') && !target.endsWith('/'))
      return null
    output[specifier] = target
  }
  return output
}

/** Validate and copy a complete import-map config section before applying it. */
export function normalizeImportMapConfig(input: unknown): ImportMapConfigValidation {
  if (input === undefined || input === null)
    return { valid: true, value: input }
  if (!isRecord(input))
    return { valid: false, diagnostic: 'importMap must be an object or null' }

  const unsupportedKeys = Object.keys(input).filter(key => key !== 'imports' && key !== 'scopes')
  if (unsupportedKeys.length > 0)
    return { valid: false, diagnostic: `importMap has unsupported option: ${unsupportedKeys[0]}` }

  const normalized: ImportMapConfig = {}
  if (input.imports !== undefined) {
    const imports = normalizeMappings(input.imports)
    if (!imports)
      return { valid: false, diagnostic: 'importMap.imports must map specifiers to HTTP URLs or URL-like relative addresses' }
    normalized.imports = imports
  }

  if (input.scopes !== undefined) {
    if (!isRecord(input.scopes))
      return { valid: false, diagnostic: 'importMap.scopes must be an object' }
    const scopes: Record<string, Record<string, string>> = Object.create(null)
    for (const [scope, rawMappings] of Object.entries(input.scopes)) {
      if (!isScopeUrlReference(scope))
        return { valid: false, diagnostic: `importMap.scopes has an invalid scope URL: ${scope}` }
      const mappings = normalizeMappings(rawMappings)
      if (!mappings)
        return { valid: false, diagnostic: `importMap.scopes[${JSON.stringify(scope)}] must map specifiers to valid HTTP or relative URLs` }
      scopes[scope] = mappings
    }
    normalized.scopes = scopes
  }

  return { valid: true, value: normalized }
}

/** Compose page, Host and AppConfig maps in precedence order without mutation. */
export function composeImportMaps(
  page?: ImportMapConfig | null,
  host?: ImportMapConfig | null,
  config?: ImportMapConfig | null,
  baseURL?: string | URL,
): ImportMapConfig {
  const imports: Record<string, string> = Object.create(null)
  const scopes: Record<string, Record<string, string>> = Object.create(null)
  let hasImports = false
  let hasScopes = false

  for (const map of [page, host, config]) {
    if (!map)
      continue
    for (const [specifier, target] of Object.entries(map.imports ?? {})) {
      const resolvedSpecifier = isUrlLikeSpecifier(specifier)
        ? resolveAgainstBase(specifier, baseURL)
        : specifier
      imports[resolvedSpecifier] = target
      hasImports = true
    }
    for (const [scope, mappings] of Object.entries(map.scopes ?? {})) {
      const resolvedScope = resolveAgainstBase(scope, baseURL)
      const merged = scopes[resolvedScope] ?? (scopes[resolvedScope] = Object.create(null))
      for (const [specifier, target] of Object.entries(mappings))
        merged[isUrlLikeSpecifier(specifier) ? resolveAgainstBase(specifier, baseURL) : specifier] = target
      hasScopes = true
    }
  }

  return {
    ...(hasImports ? { imports } : {}),
    ...(hasScopes ? { scopes } : {}),
  }
}

/** Serialize JSON for an inline script without allowing HTML/script terminators. */
export function serializeInlineJSON(value: unknown): string {
  return (JSON.stringify(value) ?? 'null').replace(/[<\u2028\u2029]/g, (character) => {
    if (character === '<')
      return '\\u003C'
    if (character === '\u2028')
      return '\\u2028'
    return '\\u2029'
  })
}

/** Serialize an import map for an inline `type="importmap"` script. */
export function serializeImportMap(map: ImportMapConfig): string {
  return serializeInlineJSON(map)
}
