import type { ImportMapConfig } from '@shared/app-config/types'
import { composeImportMaps, normalizeImportMapConfig, serializeImportMap } from '@shared/app-config/import-map'
import { APP_CONFIG_IFRAME_EVENT_TYPE } from '@shared/config/raw-env'

const MESSAGE_TYPE = APP_CONFIG_IFRAME_EVENT_TYPE || '@gen2-chat'
const GET_CONFIG = 'get-config'
const SET_CONFIG = 'set-config'

// Reframed replaces document accessors after native iframe load. Import maps
// must be registered in the physical realm, before the reflected page exists.
const physicalHead = document.head
const createPhysicalElement = document.createElement.bind(document)
const queryPhysicalDocument = document.querySelector.bind(document)

interface BootstrapOptions {
  waitForParent?: boolean
  waitForNestedInjection?: boolean
}

export interface ImportMapBootstrapApi {
  compose: (page?: ImportMapConfig | null, host?: ImportMapConfig | null, config?: ImportMapConfig | null, baseURL?: string) => ImportMapConfig
  register: (page?: ImportMapConfig | null, host?: ImportMapConfig | null, config?: ImportMapConfig | null, baseURL?: string) => ImportMapConfig
  shouldWaitForHostConfig: (search?: string) => boolean
  registerStandalone: (page?: ImportMapConfig | null, host?: ImportMapConfig | null, baseURL?: string) => Promise<Record<string, unknown>>
  waitForConfig: (options?: BootstrapOptions) => Promise<Record<string, unknown>>
  getCapturedConfig: () => { initial: unknown, updates: unknown[] }
  release: () => void
}

declare global {
  interface Window {
    WippyImportMapBootstrap?: ImportMapBootstrapApi
    __WIPPY_BOOTSTRAP_CONFIG__?: unknown
    __WIPPY_BOOTSTRAP_CONFIG_UPDATES__?: unknown[]
    __WIPPY_NESTED_CONFIG__?: unknown
  }
}

type ConfigEnvelope = Record<string, unknown> & { type: string, action: typeof SET_CONFIG }

const captureState: {
  initial: unknown
  updates: unknown[]
  listener?: (event: MessageEvent) => void
  resolveInitial?: (config: Record<string, unknown>) => void
  nestedDescriptorInstalled: boolean
} = {
  initial: undefined,
  updates: [],
  nestedDescriptorInstalled: false,
}

function physicalHostWindow(): Window | null {
  try {
    const frameElement = window.frameElement as HTMLElement | null
    const ownerWindow = frameElement?.ownerDocument?.defaultView
    if (ownerWindow && ownerWindow !== window)
      return ownerWindow
  }
  catch {}

  try {
    if (window.parent && window.parent !== window)
      return window.parent
  }
  catch {}

  return null
}

function parseConfigEnvelope(value: unknown): ConfigEnvelope | null {
  let message = value
  if (typeof message === 'string') {
    try {
      message = JSON.parse(message)
    }
    catch {
      return null
    }
  }
  if (!message || typeof message !== 'object' || Array.isArray(message))
    return null
  const candidate = message as Record<string, unknown>
  if (candidate.type !== MESSAGE_TYPE || candidate.action !== SET_CONFIG)
    return null
  return candidate as ConfigEnvelope
}

function captureConfig(config: Record<string, unknown>) {
  if (captureState.initial === undefined) {
    captureState.initial = config
    window.__WIPPY_BOOTSTRAP_CONFIG__ = config
    captureState.resolveInitial?.(config)
    captureState.resolveInitial = undefined
    return
  }

  captureState.updates.push(config)
  window.__WIPPY_BOOTSTRAP_CONFIG_UPDATES__ = [...captureState.updates]
}

function receiveSetConfig(event: MessageEvent) {
  const parent = physicalHostWindow()
  if (!parent)
    return
  const fragmentMode = (window as Window & { __WIPPY_FRAGMENT_MODE__?: boolean }).__WIPPY_FRAGMENT_MODE__ === true
  if (event.source !== (fragmentMode ? window : parent))
    return
  let expectedOrigin: string | undefined
  try {
    expectedOrigin = parent.origin
  }
  catch {}
  if (expectedOrigin && event.origin !== expectedOrigin)
    return

  const envelope = parseConfigEnvelope(event.data)
  if (!envelope)
    return
  const target = (envelope as ConfigEnvelope & { fragmentId?: unknown }).fragmentId
  if (fragmentMode) {
    const configuredId = (window.__WIPPY_BOOTSTRAP_CONFIG__ as { selfPageId?: unknown } | undefined)?.selfPageId
    const selfId = window.name.startsWith('wf:') ? window.name.slice(3) : configuredId
    if (typeof target !== 'string' || typeof selfId !== 'string' || target !== selfId)
      return
  }
  else if (target !== undefined) {
    return
  }
  const { type: _type, action: _action, ...config } = envelope
  captureConfig(config)
}

function ensureConfigListener() {
  if (captureState.listener)
    return
  captureState.listener = receiveSetConfig
  window.addEventListener('message', captureState.listener)
}

function captureNestedInjection() {
  const current = window.__WIPPY_NESTED_CONFIG__
  if (current && typeof current === 'object' && !Array.isArray(current)) {
    captureConfig(current as Record<string, unknown>)
    return
  }
  if (captureState.nestedDescriptorInstalled)
    return

  const descriptor = Object.getOwnPropertyDescriptor(window, '__WIPPY_NESTED_CONFIG__')
  if (descriptor && !descriptor.configurable)
    return

  let stored: unknown
  Object.defineProperty(window, '__WIPPY_NESTED_CONFIG__', {
    configurable: true,
    enumerable: true,
    get: () => stored,
    set: (value: unknown) => {
      stored = value
      if (value && typeof value === 'object' && !Array.isArray(value))
        captureConfig(value as Record<string, unknown>)
    },
  })
  captureState.nestedDescriptorInstalled = true
}

function waitForConfig(options: BootstrapOptions = {}): Promise<Record<string, unknown>> {
  if (captureState.initial !== undefined)
    return Promise.resolve(captureState.initial as Record<string, unknown>)

  ensureConfigListener()
  const result = new Promise<Record<string, unknown>>((resolve) => {
    captureState.resolveInitial = resolve
  })

  if (options.waitForNestedInjection)
    captureNestedInjection()

  if (captureState.initial !== undefined) {
    captureState.resolveInitial = undefined
    return Promise.resolve(captureState.initial as Record<string, unknown>)
  }

  if (options.waitForParent) {
    const parent = physicalHostWindow()
    if (parent && parent !== window) {
      try {
        parent.postMessage(JSON.stringify({ type: MESSAGE_TYPE, action: GET_CONFIG }), '*')
      }
      catch (error) {
        throw new Error(`Failed to request initial Host config: ${String(error)}`)
      }
    }
    else {
      captureConfig({})
    }
  }

  return result
}

function validatedMap(input: ImportMapConfig | null | undefined, label: string): ImportMapConfig | null | undefined {
  const result = normalizeImportMapConfig(input)
  if (!result.valid)
    throw new TypeError(`Invalid ${label} import map: ${result.diagnostic}`)
  return result.value
}

function compose(
  page?: ImportMapConfig | null,
  host?: ImportMapConfig | null,
  config?: ImportMapConfig | null,
  baseURL?: string,
): ImportMapConfig {
  return composeImportMaps(
    validatedMap(page, 'page'),
    validatedMap(host, 'Host'),
    validatedMap(config, 'AppConfig'),
    baseURL,
  )
}

function register(
  page?: ImportMapConfig | null,
  host?: ImportMapConfig | null,
  config?: ImportMapConfig | null,
  baseURL = document.baseURI,
): ImportMapConfig {
  if (queryPhysicalDocument('script[type="importmap"]'))
    throw new Error('An import map is already registered for this document')

  const map = compose(page, host, config, baseURL)
  const script = createPhysicalElement('script')
  script.type = 'importmap'
  script.textContent = serializeImportMap(map)
  physicalHead.insertBefore(script, physicalHead.firstChild)
  return map
}

function shouldWaitForHostConfig(search = window.location.search): boolean {
  return new URLSearchParams(search).has('waitForCustomConfig')
}

async function registerStandalone(
  page?: ImportMapConfig | null,
  host?: ImportMapConfig | null,
  baseURL = document.baseURI,
): Promise<Record<string, unknown>> {
  const config = shouldWaitForHostConfig()
    ? await waitForConfig({ waitForParent: true, waitForNestedInjection: true })
    : {}
  register(page, host, config.importMap as ImportMapConfig | undefined, baseURL)
  return config
}

function getCapturedConfig() {
  const initial = captureState.initial
  const updates = [...captureState.updates]
  captureState.updates = []
  window.__WIPPY_BOOTSTRAP_CONFIG_UPDATES__ = []
  return { initial, updates }
}

function release() {
  if (captureState.listener)
    window.removeEventListener('message', captureState.listener)
  captureState.listener = undefined
  const descriptor = Object.getOwnPropertyDescriptor(window, '__WIPPY_NESTED_CONFIG__')
  if (captureState.nestedDescriptorInstalled && descriptor?.configurable) {
    const capturedNestedConfig = window.__WIPPY_NESTED_CONFIG__
    Object.defineProperty(window, '__WIPPY_NESTED_CONFIG__', {
      configurable: true,
      enumerable: true,
      writable: true,
      value: capturedNestedConfig,
    })
    captureState.nestedDescriptorInstalled = false
  }
}

export const importMapBootstrap: ImportMapBootstrapApi = {
  compose,
  register,
  shouldWaitForHostConfig,
  registerStandalone,
  waitForConfig,
  getCapturedConfig,
  release,
}

if (typeof window !== 'undefined')
  window.WippyImportMapBootstrap = importMapBootstrap
